// One event, one letter, every promoter the proposal named — the
// all-or-none reservation happened upstream, so this executor either
// delivers the letter to all of them in one send or delivers nothing.
//
// This node no longer writes any of the letter. It used to: it composed the
// greeting, the band's self-description, the bullet list, the closing ask and
// the signature after the approval, which meant the band approved one sentence
// and a promoter read five paragraphs nobody at the band had seen. The letter
// is now composed in CrowdRelay at approval time and travels in `draft`, so
// what is sent here is exactly what was shown and approved. A payload without
// a draft is refused rather than filled in.
const e = $json;
if (!e || e.type !== 'crowdrelay.gig.outreach_requested' || e.version !== 1) {
  throw new Error('gig outreach refused: unsupported event');
}
const d = e.data ?? {};
const isAsk = d.template_key === 'support.slot.ask.v1';
if (d.template_key !== 'gig.proposal.v1' && !isAsk) {
  throw new Error('gig outreach refused: unknown template_key ' + d.template_key);
}
const actionId = String(d.action_id || '').trim();
const venue = String(d.venue || '').trim();
const draft = d.draft || {};
const subject = String(draft.subject || '').trim();
const body = String(draft.body || '').trim();
if (!actionId || !venue) {
  throw new Error('gig outreach refused: payload incomplete');
}
// The refusal that keeps the promise: no approved words, no send. An action
// queued before CrowdRelay composed letters carries no draft, and writing one
// here on the band's behalf is the exact thing this change removed.
if (!subject || !body) {
  throw new Error(
    'gig outreach refused: no approved letter in the payload — nothing may compose one here'
  );
}
// The address is resolved inside the sending lock upstream; a recipient
// without one means the boundary was bypassed, and that is a stop, not a
// partial send.
const recipients = Array.isArray(d.recipients) ? d.recipients : [];
const emails = [];
const targetIds = [];
for (const r of recipients) {
  const em = String((r && r.contact_email) || '').trim();
  if (!em.includes('@')) {
    throw new Error('gig outreach refused: recipient without contact_email');
  }
  emails.push(em);
  targetIds.push(String((r && r.target_id) || ''));
}
if (!emails.length) throw new Error('gig outreach refused: empty recipient set');
return [{ json: {
  event_id: e.id,
  action_id: actionId,
  city_id: String(d.city_id || ''),
  venue,
  template_key: String(d.template_key),
  // The show the ask is about, when it is one — the receipt records it so
  // the ledger can trace the letter back to the slot.
  show_event_id: d.event_id ? String(d.event_id) : null,
  recipient_count: emails.length,
  recipient_target_ids: targetIds,
  SendTo: emails.join(', '),
  SendSubject: subject.slice(0, 220),
  SendBody: body,
}}];

const claim = $json;
const intent = $('Validate the approved letter').first().json;
// A replay of an already-finished action is a no-op, not an error.
if (claim.disposition === 'already_succeeded') return [];
// claimed is the only disposition that may reach the provider; in_flight
// and ambiguous stay claimed upstream and never send twice.
if (claim.disposition !== 'claimed' || !claim.claim_token) {
  throw new Error('Provider execution ' + (claim.disposition || 'unclaimed') + '; fail closed to prevent duplicate external side effects');
}
return [{ json: { ...intent, claim_token: String(claim.claim_token), attempt_number: Number(claim.attempt_number || 1) } }];

const intent = $('Fail-closed claim gate').first().json;
const failed = Boolean($json.error);
const ref = $json.threadId || $json.thread_id || $json.id || null;
return [{ json: {
  action_id: intent.action_id,
  receipt_key: 'gig_outreach:' + intent.action_id + ':email',
  executor_id: $env.VIRYAOS_EXECUTOR_ID || 'virya-n8n-primary',
  status: failed ? 'failed' : 'succeeded',
  claim_token: intent.claim_token,
  provider_reference: failed ? null : (ref ? String(ref).slice(0, 240) : null),
  error_kind: failed ? 'gmail_send_failed' : null,
  metadata: {
    channel: 'email',
    event_id: intent.event_id,
    show_event_id: intent.show_event_id,
    venue: intent.venue,
    city_id: intent.city_id,
    recipient_count: intent.recipient_count,
    recipient_target_ids: intent.recipient_target_ids,
    template_key: intent.template_key,
  },
  occurred_at: new Date().toISOString(),
}}];
